import { generateText, streamText, jsonSchema } from "ai";

const schema = jsonSchema({
  type: "object",
  properties: { topic: { type: "string" } }
});
if (typeof generateText !== "function" || typeof streamText !== "function" || !schema) {
  throw new Error("Expected core exports from ai package");
}
